def rob_brute(nums, i):
    if i >= len(nums):
        return 0
    skip = rob_brute(nums, i + 1)                         # skip this house
    take = nums[i] + rob_brute(nums, i + 2)                 # rob this house, skip the next
    return max(skip, take)

