public class Main {
    static int rob(int[] nums) {
        int prev = 0, curr = 0;
        for (int n : nums) {
            int next = Math.max(curr, prev + n);                  // skip vs rob
            prev = curr;
            curr = next;                                             // slide the window
        }
        return curr;
    }
}

